// Curated learning relationships; destinations are exact chapter topic titles.
const GRAPH_NODES = [
['gis','GIS 基本概念',1,'信息、地理信息与 GIS','基础'],['coord','坐标系与高程',2,'坐标系与高程','基础'],['projection','地图投影',2,'地图投影及变形','基础'],['model','空间数据模型',3,'概念、逻辑与物理模型','建模'],
['object','对象与场模型',3,'对象模型与场模型','建模'],['relation','空间关系',3,'空间关系','建模'],['vector','矢量结构',4,'矢量数据结构','数据'],['raster','栅格结构',4,'栅格及压缩编码','数据'],
['topology','拓扑关系',4,'拓扑及其作用','数据'],['database','空间数据库',5,'空间数据库','数据'],['index','空间索引',5,'空间索引与查询','数据'],['acquire','数据采集',6,'空间与属性数据采集','数据'],
['processing','数据处理',6,'编辑、拓扑与几何纠正','数据'],['analysis','空间分析',7,'空间分析与空间度量','分析'],['buffer','缓冲区分析',7,'缓冲区分析','分析'],['overlay','叠置分析',7,'叠置分析','分析'],
['network','网络分析',7,'窗口分析与网络分析','分析'],['dem','数字高程模型',8,'DEM 与地形表达','分析'],['terrain','数字地形分析',8,'坡度、坡向与曲率','分析'],['statistics','空间统计',9,'空间统计与普通统计','分析'],
['visual','地理信息可视化',10,'地理信息可视化','表达'],['webgis','网络 GIS',11,'网络 GIS','表达'],['service','地理信息服务',11,'地理信息网络服务','表达'],['output','符号与地图表达',10,'符号、注记和图面配置','表达']
].map(([id,label,chapter,topic,group],i)=>({id,label,chapter,topic,group,x:100+(i%4)*240,y:70+Math.floor(i/4)*125}));
const GRAPH_EDGES = [
['gis','coord','依赖空间参考'],['coord','projection','通过投影转换'],['gis','model','通过模型抽象现实'],['model','object','包含不同概念模型'],['model','relation','描述空间关系'],['model','vector','通过结构实现'],['model','raster','通过结构实现'],['relation','topology','包括拓扑关系'],['vector','topology','可记录拓扑'],['vector','database','存储于'],['raster','database','存储于'],['database','index','利用索引加速查询'],['acquire','processing','采集后处理'],['processing','database','处理后组织入库'],['coord','processing','为空间处理提供参考：'],['database','analysis','提供分析数据'],['analysis','buffer','包括'],['analysis','overlay','包括'],['analysis','network','包括'],['raster','dem','可表示高程格网'],['dem','terrain','支持地形分析'],['analysis','statistics','结合空间统计'],['terrain','visual','结果可视化'],['statistics','visual','结果可视化'],['visual','output','使用符号表达'],['database','webgis','提供数据支撑'],['analysis','webgis','提供分析能力'],['webgis','service','提供网络服务']
].map(([from,to,relation])=>({from,to,relation}));
function graphTopic(n){const j=LESSONS[n.chapter-1].sections.findIndex(s=>s[0]===n.topic);return j<0?null:`#chapter/${n.chapter}/topic/${j}`}
function knowledgeGraph(){return `<h1 class="page-title">GIS 知识图谱</h1><p class="page-lead">从概念关系理解跨章节知识：选择节点查看它与其他知识点的联系，再进入正文学习。</p><div class="kg-intro"><div><strong>从现实世界到 GIS 应用</strong><p>节点代表核心概念，连线代表经过整理的学习关系；这是一张精选图谱，并非全部知识点。</p></div><a href="#map">查看按章节展开的思维导图</a></div><div class="kg-toolbar"><label for="kg-search">搜索概念</label><input id="kg-search" type="search" placeholder="例如：投影、缓冲区" autocomplete="off"><label for="kg-group">领域</label><select id="kg-group"><option value="">全部领域</option>${['基础','建模','数据','分析','表达'].map(g=>`<option>${g}</option>`).join('')}</select><button id="kg-reset" type="button">重置筛选</button></div><p class="kg-hint" id="kg-status" aria-live="polite">选择图中节点查看关系。手机上可横向滑动图谱。</p><div class="kg-layout"><div class="kg-canvas" tabindex="0" aria-label="可横向滚动的知识图谱"><svg class="kg-svg" viewBox="0 0 920 765" role="group" aria-label="GIS 概念关系图">${GRAPH_EDGES.map(e=>{const a=GRAPH_NODES.find(n=>n.id===e.from),b=GRAPH_NODES.find(n=>n.id===e.to);return `<line class="kg-edge" data-from="${e.from}" data-to="${e.to}" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"><title>${a.label}：${e.relation} ${b.label}</title></line>`}).join('')}${GRAPH_NODES.map(n=>`<g class="kg-node" data-node="${n.id}" data-group="${n.group}" role="button" tabindex="0" aria-label="${n.label}，第 ${n.chapter} 章"><rect x="${n.x-86}" y="${n.y-22}" width="172" height="44" rx="12"></rect><text x="${n.x}" y="${n.y+5}" text-anchor="middle">${n.label}</text></g>`).join('')}</svg></div><aside class="kg-detail" id="kg-detail" aria-live="polite"><span class="kg-detail-label">知识节点</span><h2>选择一个概念</h2><p>点击图中的节点，查看它和相邻知识点的关系。</p></aside></div><p class="kg-footnote">关系依据课程内容整理，关系方向和说明以选中节点后的文字为准；并非全部关系都具有因果性。</p>`}
function initKnowledgeGraph(){let selected=null;const search=document.querySelector('#kg-search'),group=document.querySelector('#kg-group'),status=document.querySelector('#kg-status'),detail=document.querySelector('#kg-detail');const nodes=[...document.querySelectorAll('.kg-node')],edges=[...document.querySelectorAll('.kg-edge')];function update(){const q=search.value.trim().toLowerCase(),g=group.value;const matches=GRAPH_NODES.filter(n=>(!q||n.label.toLowerCase().includes(q))&&(!g||n.group===g));const ids=new Set(matches.map(n=>n.id));nodes.forEach(el=>{const id=el.dataset.node;el.classList.toggle('kg-muted',!ids.has(id));el.classList.toggle('kg-selected',id===selected);el.classList.toggle('kg-neighbor',!!selected&&GRAPH_EDGES.some(e=>(e.from===selected&&e.to===id)||(e.to===selected&&e.from===id)))});edges.forEach(el=>{const connected=!selected||el.dataset.from===selected||el.dataset.to===selected;el.classList.toggle('kg-edge-muted',!connected||!ids.has(el.dataset.from)||!ids.has(el.dataset.to));el.classList.toggle('kg-edge-active',!!selected&&connected)});status.textContent=`符合筛选：${matches.length} / ${GRAPH_NODES.length} 个概念。选择节点查看关系；手机上可横向滑动。`}
function select(id){selected=id;const n=GRAPH_NODES.find(x=>x.id===id),links=GRAPH_EDGES.filter(e=>e.from===id||e.to===id);const dest=graphTopic(n);detail.innerHTML=`<span class="kg-detail-label">${n.group} · 第 ${n.chapter} 章</span><h2>${n.label}</h2><p>对应主题：${n.topic}</p>${dest?`<a class="btn" href="${dest}">阅读详细内容</a>`:'<p>对应主题暂不可用。</p>'}<h3>相关知识 <span>${links.length}</span></h3><ul>${links.map(e=>{const other=GRAPH_NODES.find(x=>x.id===(e.from===id?e.to:e.from));const description=e.from===id?`${n.label} ${e.relation} ${other.label}`:`${other.label} ${e.relation} ${n.label}`;return `<li><button type="button" data-related="${other.id}">${description}</button></li>`}).join('')}</ul>`;detail.querySelectorAll('[data-related]').forEach(b=>b.onclick=()=>select(b.dataset.related));update()}
nodes.forEach(el=>{el.addEventListener('click',()=>select(el.dataset.node));el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(el.dataset.node)}})});search.oninput=group.onchange=update;document.querySelector('#kg-reset').onclick=()=>{search.value='';group.value='';selected=null;detail.innerHTML='<span class="kg-detail-label">知识节点</span><h2>选择一个概念</h2><p>点击图中的节点，查看它和相邻知识点的关系。</p>';update()};update()}
